// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agents", wrapper.ListAgents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/runs", wrapper.ListRuns)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/runs/stats", wrapper.GetRunStats)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/runs/{runId}", wrapper.GetRun)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/runs/{runId}/steps", wrapper.ListRunSteps)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/runs/{runId}/verify", wrapper.VerifyRun)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/approvals", wrapper.ListApprovals)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/runs/{runId}/approvals", wrapper.DecideApproval)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/cost", wrapper.GetCostRollup)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/tools", wrapper.ListTools)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/admin/tools/{toolId}/classification", wrapper.ClassifyTool)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/integrations", wrapper.ListIntegrations)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/admin/integrations/mcp-servers/{name}", wrapper.DeleteMCPServer)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/admin/integrations/mcp-servers/{name}", wrapper.PutMCPServer)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/admin/integrations/providers/{name}", wrapper.DeleteModelProvider)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/admin/integrations/providers/{name}", wrapper.PutModelProvider)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/events", wrapper.ListAdminEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.Health)

	return m
}

